INSERT INTO feature VALUES('std-llvm','modules','The module std.llvm','packages','partial','ordinary',NULL,'`std.llvm` gives the fragment of the `llvm` dialect of MLIR that `std` admits as one `theory` block `Llvm`, with 6 sorts and 80 operations: a value has its type as an index, an attribute is an input port of a sort of constants or of `Integer` or `String`, and the rest of a body is a port of the sort `Body`; each of the 17 total operations also has a value form `val_` of the sort `Val`, and one rule takes its body form to the rest at that value; the block checks with its 17 rules and no model, and a constant of a sort is a value of `Terms Llvm` at that sort, which a `match` reads; a term of `Body` or of `Val` is refused as a type.',NULL,'library/std/src/llvm.gandr corpus/model/desc/llvm-constants-are-terms.gandr corpus/model/desc/llvm-value-layer.gandr','corpus/model/desc/llvm-constants-are-terms.gandr','#4150');
